INSERT INTO `chat_messages` VALUES (20,4,0,'Доброго здоров\'я! В мене алергія на ягоди! Зробіть без них!!!!!!!!!!!! Тільки бісквіти і крем. Знижка буде?','2026-05-14 18:57:36'),(21,4,1,'Перепрошую, але вам краще вибрати іншу позицію. ?❤️','2026-05-14 18:59:20'),(22,4,0,'Добрий день! Хочу замовити торт на день народження. У подруги непереносимість лактози, чи можете запропонувати варіант без молочних продуктів?','2026-05-18 23:23:14'),(23,4,1,'Добрий день! Так. звичайно. Ми можемо виготовити торт на рослинних вершках без використання молочних продуктів. На яку дату потрібне замовлення?','2026-05-18 23:24:07'),(24,4,0,'На 15 червня','2026-05-18 23:24:14'),(25,4,1,'Добре. На скільки осіб розрахований торт?','2026-05-18 23:24:50'),(26,4,0,'Приблизно на 10-12 осіб','2026-05-18 23:25:03'),(27,4,1,'Який смак ви б хотіли: шоколадний, ванільний чи ягідний?','2026-05-18 23:25:21'),(28,4,0,'Шоколадний з вишневою начинкою','2026-05-18 23:25:40'),(29,4,1,'Чудовий вибір! Чи є ще якісь побажання або обмеження щодо складу?','2026-05-18 23:26:09'),(30,7,0,'lj,hbq ltym','2026-05-24 17:53:37');
/*!40000 ALTER TABLE `chat_messages` ENABLE KEYS */;
UNLOCK TABLES;

