CREATE TABLE `orders` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint DEFAULT NULL,
  `composition` text NOT NULL,
  `weight_kg` double DEFAULT NULL,
  `address` varchar(300) DEFAULT NULL,
  `comment` text,
  `ai_image_url` longtext,
  `constructor_img` longtext,
  `deadline` datetime DEFAULT NULL,
  `price` int DEFAULT NULL,
  `payment_status` enum('ON_DELIVERY','PAID') DEFAULT 'ON_DELIVERY',
  `order_status` enum('NEW','IN_PROGRESS','READY','DONE','CANCELLED') DEFAULT 'NEW',
  `admin_note` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `first_image_path` varchar(255) DEFAULT NULL,
  `images_json` longtext,
  `military_sweets` bit(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
