DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL,
  `description` text,
  `price` int NOT NULL,
  `price_unit` varchar(50) DEFAULT 'шт',
  `image_path` varchar(500) DEFAULT NULL,
  `available` tinyint(1) DEFAULT '1',
  `catalog_type` enum('FLAVOR','DESIGN','LINE') NOT NULL,
  `design_event` enum('BIRTHDAY','FOR_GIRL','FOR_BOY','FOR_WOMAN','FOR_MAN','WEDDING','CHRISTENING','COMMUNION','CORPORATE','ROMANTIC','SEASONAL') DEFAULT NULL,
  `design_for` varchar(200) DEFAULT NULL,
  `dietary_tags` varchar(255) DEFAULT NULL,
  `flavor_base` enum('CHOCOLATE','BERRY_FRUIT','NUT_CARAMEL','CREAM_MOUSSE','CHEESECAKE') DEFAULT NULL,
  `product_line` enum('BENTO','PORTION','CUPCAKE','MACARONS','CAKE_POPS','SWEET_BOX','CANDY_BAR','DECOR','CANDLES','TOPPERS','CARDS') DEFAULT NULL,
  `urgency` enum('TODAY','HOURS_24','HOURS_48') DEFAULT NULL,
  `discount_percent` int DEFAULT '0',
  `flavor_description` text,
  `ingredients` text,
  `calories` varchar(100) DEFAULT NULL,
  `allergens` varchar(255) DEFAULT NULL,
  `min_weight_kg` double DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

